async function api(path: string, init?: RequestInit) {
  const response = await fetch(path, { cache:'no-store',...init, headers: { ...propertyHeaders(),...(init?.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...init?.headers } });
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Something went wrong. Please try again.');
  return result;
}
function Avatar({ member, small = false }: { member?: Member; small?: boolean }) { return <span className={`avatar ${small ? 'small' : ''}`} style={{ backgroundColor: member?.color || '#e6eaf3' }}>{member?.name.slice(0, 1) || '?'}</span>; }
function Badge({ label }: { label: string }) { return <span className={`badge ${label === 'Approved' ? 'green' : ['Overdue', 'Rejected', 'Tasks to fix'].includes(label) ? 'red' : ['In review', 'Part submitted', 'Your part submitted', 'Late'].includes(label) ? 'amber' : label === 'Due today' ? 'blue' : ''}`}>{label}</span>; }
function useCleaningClock(serverNow?: string, fallbackDate?: string): CleaningClock {
  const [, tick] = useState(0);
  const basis = useMemo(() => ({ server: serverNow && Number.isFinite(Date.parse(serverNow)) ? Date.parse(serverNow) : Date.now(), client: Date.now() }), [serverNow]);
  useEffect(() => { const timer = setInterval(() => tick(value => value + 1), 15000); return () => clearInterval(timer); }, []);
  const current = localClock(new Date(basis.server + Date.now() - basis.client));
  return serverNow ? current : { ...current, date: fallbackDate || current.date };
}
